service.description:
Stores john.doe's (EX_JOHN_DOE) demo Today and notifications, dated from now in john.doe's time zone in a
            data load (the user's when a user runs it), so each shows at its time of day; a load on a later day moves them and keeps
            one Assignee row per party:
            - BOSS_DEMO_TODAY_OVERDUE, a task due two days ago at 17:00 on Bob Acme's party (WorkEffortRecord): Overdue;
            - BOSS_DEMO_TODAY_CALL, a call (WepPhoneCall) due today at 11:00 on the demo request (RequestWorkEffort): Due today;
            - BOSS_DEMO_TODAY_DUE, a task due today at 17:00 that Joe Developer is also assigned: Due today;
            - BOSS_DEMO_TODAY_MEETING, a meeting today at 15:00 for 30 minutes (from 14:00 an hour from now): Later today;
            - the demo request's response due today at 16:00, which the Requests today source lists, and the times of day of the
              demo request, event and message of data/BossDemoData.xml;
            - notifications in the Notifications inbox (a mention, a reminder, a chat mention, an invitation read yesterday
              and an approval waiting on the BossDemoApproval topic) and in the Updates inbox (a followed-record note, an
              invitation answer, and one read two days ago).

actions.script:
workEffortIdList = []
notificationMessageIdList = []
const partyId = 'EX_JOHN_DOE'
const userId = 'EX_JOHN_DOE'
if (ec.entity.find('mantle.party.Party').condition('partyId', partyId).disableAuthz().one() == null) {
    ec.logger.warn('The Commons demo needs the party EX_JOHN_DOE (mantle-usl demo data); nothing loaded')
    return
}
// john.doe's time zone for every time of day here, whatever the server's is (a data load has no user), as the calendar
// demo has it; the user's own when a user runs it
const account = ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
const zone = account?.timeZone || 'US/Central'
const signedIn = !!ec.user.userId
const previousZone = ec.user.timeZone
if (!signedIn && zone !== previousZone) ec.user.setTimeZone(zone)
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const toMillis = (value) => {
        if (value == null || value === '') return null
        if (typeof value === 'number') return value
        if (value instanceof Date) return value.getTime()
        const text = String(value)
        return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
    }
    const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
    const nowMillis = toMillis(ec.user.nowTimestamp)
    const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
    const at = (text, time) => toMillis(ec.l10n.parseTimestamp(text + ' ' + time + ':00.000', pattern))
    const todayText = dayText(nowMillis)
    const todayStart = at(todayText, '00:00')
    // a day is 23 to 25 hours, so 12 hours before a day's start is in the day before and 30 hours after it in the next
    const daysFrom = (text, days) => {
        let millis = at(text, '00:00')
        for (let i = 0; i < Math.abs(days); i++) millis = at(dayText(millis + (days < 0 ? -12 : 30) * 3600000), '00:00')
        return dayText(millis)
    }
    const twoDaysAgo = daysFrom(todayText, -2)
    const store = (entityName, fields) => {
        ec.service.sync().name('store#' + entityName).parameters(fields).disableAuthz().call()
    }
    const fromDate = new Date(todayStart - 7 * 86400000)

    // the work efforts and john.doe's rows on them: one Assignee row per party whatever the day of the load (its
    // fromDate is a key: a load on a later day keeps the first row's, and the rows earlier loads added on other days go)
    const workEffort = (id, fields, assignees) => {
        // written as a value, not through store#: a load on a later day puts the item back as it was, done or not, which
        // the status flow would not allow (Complete to Approved)
        const value = ec.entity.makeValue('mantle.work.effort.WorkEffort')
        for (const [field, fieldValue] of Object.entries(Object.assign({workEffortId: id, statusId: fields.workEffortTypeEnumId === 'WetEvent' ? 'WeInPlanning' : 'WeApproved',
                resolutionEnumId: 'WerUnresolved', ownerPartyId: partyId, timeUomId: 'TF_hr'}, fields))) value.set(field, fieldValue)
        value.createOrUpdate()
        for (const assignee of assignees) {
            const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', id).condition('partyId', assignee)
                    .condition('roleTypeId', 'Assignee').orderBy('fromDate').list())
            for (const extra of rows.slice(1)) extra.delete()
            store('mantle.work.effort.WorkEffortParty', {workEffortId: id, partyId: assignee, roleTypeId: 'Assignee',
                fromDate: rows.length ? rows[0].fromDate : fromDate, thruDate: null, statusId: 'WeptAssigned', snoozedThruDate: null})
        }
        workEffortIdList.push(id)
    }
    workEffort('BOSS_DEMO_TODAY_OVERDUE', {workEffortTypeEnumId: 'WetTask', purposeEnumId: 'WepTask', priority: 3,
        workEffortName: 'Send the signed service agreement to Bob Acme', description: 'The agreement for the team calendar setup, signed on both pages.',
        estimatedCompletionDate: new Date(at(twoDaysAgo, '17:00')), estimatedWorkTime: 1, remainingWorkTime: 1}, [partyId])
    store('mantle.work.effort.WorkEffortRecord', {workEffortId: 'BOSS_DEMO_TODAY_OVERDUE', recordEntityName: 'mantle.party.Party',
        recordId: 'ORG_ACME_BA', linkedByUserId: userId, linkedDate: fromDate})
    workEffort('BOSS_DEMO_TODAY_CALL', {workEffortTypeEnumId: 'WetTask', purposeEnumId: 'WepPhoneCall', priority: 4,
        workEffortName: 'Call Bob Acme about who may see the shared calendar', estimatedCompletionDate: new Date(at(todayText, '11:00'))}, [partyId])
    store('mantle.request.RequestWorkEffort', {requestId: 'BOSS_DEMO_REQUEST', workEffortId: 'BOSS_DEMO_TODAY_CALL'})
    workEffort('BOSS_DEMO_TODAY_DUE', {workEffortTypeEnumId: 'WetTask', purposeEnumId: 'WepTask', priority: 5,
        workEffortName: 'Compare the calendar options for the team', description: 'Two or three options with their cost and how they share.',
        estimatedCompletionDate: new Date(at(todayText, '17:00')), estimatedWorkTime: 2, remainingWorkTime: 2}, [partyId, 'ORG_ZIZI_JD'])
    // the meeting starts at 15:00, or an hour from now (on the half hour) once that is past
    let meetingStart = at(todayText, '15:00')
    if (nowMillis > at(todayText, '14:00')) meetingStart = Math.ceil((nowMillis + 3600000) / 1800000) * 1800000
    workEffort('BOSS_DEMO_TODAY_MEETING', {workEffortTypeEnumId: 'WetEvent', purposeEnumId: 'WepMeeting', priority: 5,
        workEffortName: 'Calendar setup review', description: 'Go over the options and pick one.',
        estimatedStartDate: new Date(meetingStart), estimatedCompletionDate: new Date(meetingStart + 1800000), estimatedWorkDuration: 0.5}, [partyId, 'ORG_ZIZI_JD'])
    // the demo request (BossDemoData.xml) has a response due today, for the Requests today source; it, the demo event and
    // the demo message of the data file get their times of day here, in john.doe's zone (a data file's times load as UTC)
    store('mantle.request.Request', {requestId: 'BOSS_DEMO_REQUEST', requestDate: new Date(at('2026-10-01', '09:00')),
        responseRequiredDate: new Date(at(todayText, '16:00'))})
    store('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_DEMO_EVENT', estimatedStartDate: new Date(at('2026-10-21', '10:00'))})
    store('mantle.party.communication.CommunicationEvent', {communicationEventId: 'BOSS_DEMO_MESSAGE', entryDate: new Date(at('2026-10-15', '14:30'))})

    // the notifications: the message and john.doe's row, read or not
    const hours = (count) => new Date(nowMillis - count * 3600000)
    const notification = (id, fields, viewedDate) => {
        const sentDate = fields.sentDate
        store('moqui.security.user.NotificationMessage', Object.assign({notificationMessageId: id, showAlert: 'N', typeString: 'info'}, fields,
            {messageJson: fields.messageJson ? JSON.stringify(fields.messageJson) : null}))
        store('moqui.security.user.NotificationMessageUser', {notificationMessageId: id, userId: userId, sentDate: sentDate,
            viewedDate: viewedDate || null})
        notificationMessageIdList.push(id)
    }
    const request = {recordEntityName: 'mantle.request.Request', recordId: 'BOSS_DEMO_REQUEST'}
    notification('BOSS_DEMO_NM_MENTION', Object.assign({topic: 'ChatterMention', reasonEnumId: 'NrMention', actorUserId: 'ORG_ZIZI_JD',
        appName: 'Commons', sentDate: hours(2), titleText: 'Joe Developer mentioned you on Request BOSS_DEMO_REQUEST: can the contractors see it too?',
        messageJson: {recordName: 'Set up the shared team calendar', authorName: 'Joe Developer', summary: 'can the contractors see it too?'}}, request))
    notification('BOSS_DEMO_NM_REMINDER', {topic: 'WorkEffortReminder', reasonEnumId: 'NrReminder', appName: 'Commons', sentDate: hours(0.5),
        recordEntityName: 'mantle.work.effort.WorkEffort', recordId: 'BOSS_DEMO_TODAY_DUE',
        titleText: 'Reminder: Compare the calendar options for the team, due today',
        messageJson: {workEffortId: 'BOSS_DEMO_TODAY_DUE', workEffortName: 'Compare the calendar options for the team', whenText: 'due today'}})
    notification('BOSS_DEMO_NM_CHAT', {topic: 'ChatMention', reasonEnumId: 'NrMention', actorUserId: 'ORG_ZIZI_BD', appName: 'Comms',
        sentDate: hours(5), titleText: 'Bob Developer mentioned you in Team: lunch on Friday?', linkText: '/qapps/Comms/Chat?chatRoomId=BOSS_DEMO_CHAT_TEAM&eventSeq=4',
        messageJson: {roomName: 'Team', authorName: 'Bob Developer', summary: 'lunch on Friday?'}})
    notification('BOSS_DEMO_NM_INVITE', {topic: 'EventInvitation', reasonEnumId: 'NrAssignment', actorUserId: 'ORG_ZIZI_JD', appName: 'Commons',
        sentDate: hours(26), recordEntityName: 'mantle.work.effort.WorkEffort', recordId: 'BOSS_DEMO_EVENT',
        titleText: 'Joe Developer invited you to Weekly team meeting',
        messageJson: {workEffortId: 'BOSS_DEMO_EVENT', workEffortName: 'Weekly team meeting', organizerName: 'Joe Developer'}}, hours(20))
    notification('BOSS_DEMO_NM_APPROVAL', Object.assign({topic: 'BossDemoApproval', reasonEnumId: 'NrApproval', actorUserId: 'ORG_ZIZI_JD',
        appName: 'Commons', sentDate: hours(3), titleText: 'Approve the shared calendar subscription: USD 120.00 a year',
        messageJson: {summary: 'Shared calendar subscription for the team', amount: '120.00', currencyUomId: 'USD', requestedByName: 'Joe Developer'}}, request))
    notification('BOSS_DEMO_NM_FOLLOW', Object.assign({topic: 'RecordFollow', reasonEnumId: 'NrComment', actorUserId: 'ORG_ZIZI_JD', appName: 'Commons',
        sentDate: hours(4), titleText: 'Joe Developer on Request BOSS_DEMO_REQUEST: added the meeting room calendar to the list',
        messageJson: {recordName: 'Set up the shared team calendar', authorName: 'Joe Developer', summary: 'added the meeting room calendar to the list'}}, request))
    notification('BOSS_DEMO_NM_ANSWER', {topic: 'EventInvitationResponse', reasonEnumId: 'NrSystem', actorUserId: 'ORG_ZIZI_BD', appName: 'Commons',
        sentDate: hours(6), recordEntityName: 'mantle.work.effort.WorkEffort', recordId: 'BOSS_DEMO_EVENT',
        titleText: 'Bob Developer accepted Weekly team meeting',
        messageJson: {workEffortId: 'BOSS_DEMO_EVENT', workEffortName: 'Weekly team meeting', responderName: 'Bob Developer', responseText: 'accepted'}})
    notification('BOSS_DEMO_NM_UPDATE_OLD', Object.assign({topic: 'RecordFollow', reasonEnumId: 'NrComment', actorUserId: 'ORG_ZIZI_BD', appName: 'Commons',
        sentDate: hours(50), titleText: 'Bob Developer on Request BOSS_DEMO_REQUEST: the old calendar export is attached',
        messageJson: {recordName: 'Set up the shared team calendar', authorName: 'Bob Developer', summary: 'the old calendar export is attached'}}, request), hours(48))
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
    if (!signedIn && zone !== previousZone) ec.user.setTimeZone(previousZone || null)
}

communicationEventIdList = []
workEffortIdList = []
if (ec.entity.find('mantle.party.Party').condition('partyId', 'EX_JOHN_DOE').disableAuthz().one() == null) {
    ec.logger.warn('The Chatter demo needs the party EX_JOHN_DOE (mantle-usl demo data); nothing loaded')
    return
}
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const ts = (text) => ec.l10n.parseTimestamp(text + ':00.000', pattern)
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const nowMillis = toMillis(ec.user.nowTimestamp)
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
// a day from today at a time: a day is 23 to 25 hours, so 30 hours after a day's start is in the next one
const inDays = (days, time) => {
    let text = dayText(nowMillis)
    for (let i = 0; i < days; i++) text = dayText(toMillis(ts(text + ' 00:00')) + 30 * 3600000)
    return ts(text + ' ' + time)
}
// john.doe's time zone for the times of day, whatever the server's is (a data load has no user), as the calendar demo
const account = ec.entity.find('moqui.security.UserAccount').condition('userId', 'EX_JOHN_DOE').disableAuthz().one()
const zone = account?.timeZone || 'US/Central'
const signedIn = !!ec.user.userId
const previousZone = ec.user.timeZone
if (!signedIn && zone !== previousZone) ec.user.setTimeZone(zone)
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const store = (entityName, fields) => ec.service.sync().name('store#' + entityName).parameters(fields).call()
    const request = {entity: 'mantle.request.RequestCommEvent', keys: {requestId: 'BOSS_DEMO_REQUEST'}}
    const task = {entity: 'mantle.work.effort.WorkEffortCommEvent', keys: {workEffortId: 'BOSS_DEMO_TASK'}}
    const event = {entity: 'mantle.work.effort.WorkEffortCommEvent', keys: {workEffortId: 'BOSS_DEMO_EVENT'}}
    const note = (id, from, date, body, on) => {
        store('mantle.party.communication.CommunicationEvent', {communicationEventId: id, communicationEventTypeId: 'Comment',
            contactMechTypeEnumId: 'CmtWebForm', statusId: 'CeSent', fromPartyId: from, entryDate: ts(date), contentType: 'text/html', body: body})
        store(on.entity, Object.assign({communicationEventId: id}, on.keys))
        communicationEventIdList.push(id)
    }

    // the request: notes, an email with its quoted text, the message of the Comms demo, a call done, a status change
    note('BOSS_DEMO_CE_NOTE1', 'ORG_ZIZI_JD', '2026-10-02 10:15', '<p>Contractors should get <strong>view</strong> access only. ' +
        '<span data-mention-id="EX_JOHN_DOE">@John Doe</span>, can you confirm that with Bob?</p>', request)
    store('mantle.party.communication.CommunicationEvent', {communicationEventId: 'BOSS_DEMO_CE_EMAIL1', communicationEventTypeId: 'Email',
        contactMechTypeEnumId: 'CmtEmailAddress', statusId: 'CeReceived', fromPartyId: 'ORG_ACME_BA', toPartyId: 'EX_JOHN_DOE',
        entryDate: ts('2026-10-02 16:40'), subject: 'Re: The shared team calendar', contentType: 'text/plain',
        body: 'Hi John,\n\nYes, view access for the contractors is fine. Please add the two meeting rooms as well.\n\nThanks,\nBob\n\n' +
            'On Thu, Oct 2, 2026 at 11:02 AM John Doe wrote:\n> Bob, should the contractors see the shared calendar?\n' +
            '> We can give them view access only.'})
    store(request.entity, Object.assign({communicationEventId: 'BOSS_DEMO_CE_EMAIL1'}, request.keys))
    communicationEventIdList.push('BOSS_DEMO_CE_EMAIL1')
    note('BOSS_DEMO_CE_NOTE2', 'EX_JOHN_DOE', '2026-10-03 09:30', '<p>Confirmed with Bob: view access for the contractors, and the ' +
        'two meeting rooms as resources.</p><ul><li>Room A, 8 seats</li><li>Room B, 12 seats</li></ul>', request)
    store(request.entity, Object.assign({communicationEventId: 'BOSS_DEMO_MESSAGE'}, request.keys))
    store('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_DEMO_DONE_CALL', workEffortTypeEnumId: 'WetTask', purposeEnumId: 'WepPhoneCall',
        statusId: 'WeComplete', resolutionEnumId: 'WerCompleted', priority: 5, ownerPartyId: 'EX_JOHN_DOE', timeUomId: 'TF_hr',
        workEffortName: 'Call Bob Acme about the calendar options', description: 'Bob prefers the option with room booking.',
        estimatedCompletionDate: ts('2026-10-02 11:00'), actualCompletionDate: ts('2026-10-02 11:20')})
    store('mantle.work.effort.WorkEffortParty', {workEffortId: 'BOSS_DEMO_DONE_CALL', partyId: 'EX_JOHN_DOE', roleTypeId: 'Assignee',
        fromDate: ts('2026-10-01 09:00'), statusId: 'WeptAssigned'})
    store('mantle.request.RequestWorkEffort', {requestId: 'BOSS_DEMO_REQUEST', workEffortId: 'BOSS_DEMO_DONE_CALL'})
    workEffortIdList.push('BOSS_DEMO_DONE_CALL')
    // an audit log row is create-only: written once
    if (ec.entity.find('moqui.entity.EntityAuditLog').condition('auditHistorySeqId', 'BOSS_DEMO_AUDIT_REQ1').one() == null)
        ec.service.sync().name('create#moqui.entity.EntityAuditLog').parameters({auditHistorySeqId: 'BOSS_DEMO_AUDIT_REQ1',
            changedEntityName: 'mantle.request.Request', changedFieldName: 'statusId', pkPrimaryValue: 'BOSS_DEMO_REQUEST',
            oldValueText: 'ReqDraft', newValueText: 'ReqSubmitted', changedDate: ts('2026-10-01 09:05'), changedByUserId: 'EX_JOHN_DOE'}).call()
    for (const userId of ['EX_JOHN_DOE', 'ORG_ZIZI_JD']) store('mantle.party.communication.RecordFollower', {recordEntityName: 'mantle.request.Request',
        recordId: 'BOSS_DEMO_REQUEST', userId: userId, fromDate: ts('2026-10-01 09:00'), notifyMessages: 'Y', notifyNotes: 'Y',
        notifyActivities: 'Y', notifyChanges: 'N'})

    // the files: the content rows and their files in the database resources
    const root = 'dbresource://mantle/content'
    const file = (entityName, idField, id, fields, folder, name, content) => {
        const location = `${root}/${folder}/content_${id}/${name}`
        const ref = ec.resource.getLocationReference(location)
        if (content.copyFrom) ref.copyFrom(content.copyFrom)
        else ref.putText(content.text)
        store(entityName, Object.assign({[idField]: id, contentLocation: location, userId: 'EX_JOHN_DOE'}, fields))
    }
    file('mantle.request.RequestContent', 'requestContentId', 'BOSS_DEMO_RC_OPTIONS', {requestId: 'BOSS_DEMO_REQUEST',
        contentTypeEnumId: 'RqCntInternal', contentDate: ts('2026-10-02 12:00'), description: 'The three calendar options compared'},
        'request/BOSS_DEMO_REQUEST', 'calendar-options.txt', {text: 'Calendar options for the team\n\n' +
            '1. Shared calendar in Commons: free, room booking, view-only sharing for contractors\n' +
            '2. Hosted calendar service: USD 120.00 a year, room booking\n3. Paper wall planner: no sharing\n'})
    file('mantle.request.RequestContent', 'requestContentId', 'BOSS_DEMO_RC_PICTURE', {requestId: 'BOSS_DEMO_REQUEST',
        contentTypeEnumId: 'RqCntInternal', contentDate: ts('2026-10-03 09:40'), description: 'How the shared calendar will look'},
        'request/BOSS_DEMO_REQUEST', 'team-calendar.png', {copyFrom: 'component://ironstone-boss/data/demo/team-calendar.png'})

    // the task: a note, a to-do done, an email planned in two days, a file
    note('BOSS_DEMO_CE_NOTE3', 'EX_JOHN_DOE', '2026-10-06 14:00', '<p>Three requests are open; two wait on the customer.</p>', task)
    const activity = (id, fields, on) => {
        store('mantle.work.effort.WorkEffort', Object.assign({workEffortId: id, workEffortTypeEnumId: 'WetTask', resolutionEnumId: 'WerUnresolved',
            priority: 5, ownerPartyId: 'EX_JOHN_DOE', timeUomId: 'TF_hr'}, fields))
        store('mantle.work.effort.WorkEffortParty', {workEffortId: id, partyId: 'EX_JOHN_DOE', roleTypeId: 'Assignee',
            fromDate: ts('2026-10-01 09:00'), statusId: 'WeptAssigned'})
        store('mantle.work.effort.WorkEffortRecord', {workEffortId: id, recordEntityName: 'mantle.work.effort.WorkEffort', recordId: on,
            linkedByUserId: 'EX_JOHN_DOE', linkedDate: ts('2026-10-06 14:05')})
        workEffortIdList.push(id)
    }
    activity('BOSS_DEMO_TASK_DONE', {purposeEnumId: 'WepToDo', statusId: 'WeComplete', resolutionEnumId: 'WerCompleted',
        workEffortName: 'Sort the open requests by customer', estimatedCompletionDate: ts('2026-10-06 15:00'),
        actualCompletionDate: ts('2026-10-06 15:10')}, 'BOSS_DEMO_TASK')
    activity('BOSS_DEMO_TASK_EMAIL', {purposeEnumId: 'WepEmail', statusId: 'WeInPlanning', workEffortName: 'Email the customers waiting on an answer',
        estimatedCompletionDate: inDays(2, '10:00'), actualCompletionDate: null}, 'BOSS_DEMO_TASK')
    file('mantle.work.effort.WorkEffortContent', 'workEffortContentId', 'BOSS_DEMO_WC_LIST', {workEffortId: 'BOSS_DEMO_TASK',
        contentTypeEnumId: 'WectSupportingMedia', contentDate: ts('2026-10-06 14:30'), description: 'The open requests'},
        'work/BOSS_DEMO_TASK', 'open-requests.csv', {text: 'requestId,name,customer\nBOSS_DEMO_REQUEST,Set up the shared team calendar,Bob Acme\n'})

    // the event: a note, a to-do planned in three days, an agenda
    note('BOSS_DEMO_CE_NOTE4', 'ORG_ZIZI_JD', '2026-10-07 08:45', '<p>Agenda: the calendar rollout, then the open requests.</p>', event)
    activity('BOSS_DEMO_EVENT_TODO', {purposeEnumId: 'WepToDo', statusId: 'WeInPlanning', workEffortName: 'Book the large meeting room',
        estimatedCompletionDate: inDays(3, '12:00'), actualCompletionDate: null}, 'BOSS_DEMO_EVENT')
    file('mantle.work.effort.WorkEffortContent', 'workEffortContentId', 'BOSS_DEMO_WC_AGENDA', {workEffortId: 'BOSS_DEMO_EVENT',
        contentTypeEnumId: 'WectSupportingMedia', contentDate: ts('2026-10-07 08:50'), description: 'Agenda of the weekly meeting'},
        'work/BOSS_DEMO_EVENT', 'agenda.txt', {text: 'Weekly team meeting\n\n1. Calendar rollout\n2. Open requests\n3. Anything else\n'})
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
    if (!signedIn && zone !== previousZone) ec.user.setTimeZone(previousZone || null)
}

const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (ec.entity.find('mantle.party.Party').condition('partyId', 'BOSS_DEMO_PC_ROBIN').one() == null) {
        ec.logger.warn('The Contacts demo needs BOSS_DEMO_PC_ROBIN (data/BossDemoData.xml); nothing loaded')
        return
    }
    const now = Number(String(ec.user.nowTimestamp))
    const sent = (id, toPartyId, days, subject, body) => ec.service.sync().name('store#mantle.party.communication.CommunicationEvent')
            .parameters({communicationEventId: id, communicationEventTypeId: 'Email', statusId: 'CeSent', fromPartyId: 'EX_JOHN_DOE',
                toPartyId: toPartyId, entryDate: new Date(now - days * 86400000), subject: subject, contentType: 'text/plain', body: body}).call()
    sent('BOSS_DEMO_CE_CONTACT_ROBIN', 'BOSS_DEMO_PC_ROBIN', 3, 'Dinner on Saturday', 'Are you free for dinner on Saturday?')
    sent('BOSS_DEMO_CE_CONTACT_PAT', 'BOSS_DEMO_DUP_A', 6, 'Your calendar question', 'The shared calendar can be read by the whole team.')
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
}

service.description:
The tasks and requests of IronStone Commons M6 (design-drawers-commons.md §8), so every smart list of
            john.doe (EX_JOHN_DOE) has rows, dated from the load (none overdue or due today, which the Today demo has):
            - the project BOSS_DEMO_PROJECT (Office move), john.doe its manager, with the task BOSS_DEMO_TASK_PLAN (Plan the office
              move, in progress, due in five days, with two hours john.doe logged yesterday) and its sub-tasks: Get quotes from two
              movers (john.doe, in three days), Draw the new floor plan (made by john.doe, assigned to Joe Developer, in six days)
              and Order packing boxes (done yesterday);
            - BOSS_DEMO_TASK_WATCH (Renew the domain name), Joe Developer's, which john.doe watches, due in two days;
            - BOSS_DEMO_TASK_FROMJOE (Check the backup restore), made by Joe Developer and assigned to john.doe, with no due date;
            - the demo task BOSS_DEMO_TASK due in four days (it had a fixed date);
            - the requests BOSS_DEMO_REQ_DRAFT (a draft john.doe raised), BOSS_DEMO_REQ_ASSIGNED (raised by Joe Developer, in
              progress, assigned to john.doe), BOSS_DEMO_REQ_WATCH (raised by Joe Developer, reviewed, john.doe a watcher) and
              BOSS_DEMO_REQ_DONE (john.doe's, completed).
            The times of day are in john.doe's time zone (the user's when a user runs it). Only BOSS_DEMO_* records are written;
            loading again moves their dates.

actions.script:
workEffortIdList = []
requestIdList = []
// john.doe's time zone for the times of day, whatever the server's is (a data load has no user), as the calendar demo
const account = ec.entity.find('moqui.security.UserAccount').condition('userId', 'EX_JOHN_DOE').disableAuthz().one()
const zone = account?.timeZone || 'US/Central'
const signedIn = !!ec.user.userId
const previousZone = ec.user.timeZone
if (!signedIn && zone !== previousZone) ec.user.setTimeZone(zone)
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (ec.entity.find('mantle.party.Party').condition('partyId', 'EX_JOHN_DOE').one() == null) {
        ec.logger.warn('The Tasks demo needs the party EX_JOHN_DOE (mantle-usl demo data); nothing loaded')
        return
    }
    const john = 'EX_JOHN_DOE'
    const joe = 'ORG_ZIZI_JD'
    const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
    const toMillis = (value) => {
        if (value == null || value === '') return null
        if (typeof value === 'number') return value
        if (value instanceof Date) return value.getTime()
        const text = String(value)
        return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
    }
    const nowMillis = toMillis(ec.user.nowTimestamp)
    const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
    const at = (text, time) => ec.l10n.parseTimestamp(text + ' ' + time + ':00.000', pattern)
    // a day from today at a time: a day is 23 to 25 hours, so 30 hours after a day's start is in the next one and 12
    // hours before it in the one before
    const inDays = (days, time) => {
        let text = dayText(nowMillis)
        for (let i = 0; i < Math.abs(days); i++) text = dayText(toMillis(at(text, '00:00')) + (days < 0 ? -12 : 30) * 3600000)
        return at(text, time)
    }
    // the party rows from a fixed time, so a load in another time zone or on another day finds the same rows
    const fromDate = new Date(Date.UTC(2026, 9, 1, 13, 0))
    const store = (entityName, fields) => ec.service.sync().name('store#' + entityName).parameters(fields).call()
    // a status is set when the record is made: a later load leaves a status someone changed as it is (the status
    // flow may have no way back)
    const storeWithStatus = (entityName, keyField, fields) => {
        const values = Object.assign({}, fields)
        if (ec.entity.find(entityName).condition(keyField, values[keyField]).one() != null) delete values.statusId
        store(entityName, values)
    }
    const task = (id, fields, parties) => {
        storeWithStatus('mantle.work.effort.WorkEffort', 'workEffortId', Object.assign({workEffortId: id, workEffortTypeEnumId: 'WetTask', purposeEnumId: 'WepTask',
            statusId: 'WeInPlanning', resolutionEnumId: 'WerUnresolved', priority: 5, ownerPartyId: john, timeUomId: 'TF_hr'}, fields))
        for (const [partyId, roleTypeId] of parties) store('mantle.work.effort.WorkEffortParty', {workEffortId: id, partyId: partyId,
            roleTypeId: roleTypeId, fromDate: fromDate, statusId: 'WeptAssigned', snoozedThruDate: null})
        workEffortIdList.push(id)
    }

    // the project and its planning task with sub-tasks and time
    storeWithStatus('mantle.work.effort.WorkEffort', 'workEffortId', {workEffortId: 'BOSS_DEMO_PROJECT', workEffortTypeEnumId: 'WetProject', statusId: 'WeInProgress',
        resolutionEnumId: 'WerUnresolved', ownerPartyId: john, workEffortName: 'Office move', timeUomId: 'TF_hr',
        description: 'The move to the new office on the third floor.', estimatedStartDate: inDays(-14, '09:00'), estimatedCompletionDate: inDays(30, '17:00')})
    store('mantle.work.effort.WorkEffortParty', {workEffortId: 'BOSS_DEMO_PROJECT', partyId: john, roleTypeId: 'Manager', fromDate: fromDate,
        statusId: 'WeptAssigned'})
    store('mantle.work.effort.WorkEffortParty', {workEffortId: 'BOSS_DEMO_PROJECT', partyId: joe, roleTypeId: 'Assignee', fromDate: fromDate,
        statusId: 'WeptAssigned'})
    workEffortIdList.push('BOSS_DEMO_PROJECT')
    task('BOSS_DEMO_TASK_PLAN', {workEffortName: 'Plan the office move', statusId: 'WeInProgress', priority: 2, rootWorkEffortId: 'BOSS_DEMO_PROJECT',
        description: 'Who moves when, what goes where, and the movers.', estimatedCompletionDate: inDays(5, '17:00'),
        estimatedWorkTime: 6, remainingWorkTime: 4, actualWorkTime: 2}, [[john, 'Assignee']])
    task('BOSS_DEMO_SUB_MOVERS', {workEffortName: 'Get quotes from two movers', priority: 3, parentWorkEffortId: 'BOSS_DEMO_TASK_PLAN',
        rootWorkEffortId: 'BOSS_DEMO_PROJECT', estimatedCompletionDate: inDays(3, '00:00')}, [[john, 'Assignee']])
    task('BOSS_DEMO_SUB_FLOORPLAN', {workEffortName: 'Draw the new floor plan', priority: 4, parentWorkEffortId: 'BOSS_DEMO_TASK_PLAN',
        rootWorkEffortId: 'BOSS_DEMO_PROJECT', estimatedCompletionDate: inDays(6, '00:00'), estimatedWorkTime: 3, remainingWorkTime: 3}, [[joe, 'Assignee']])
    task('BOSS_DEMO_SUB_BOXES', {workEffortName: 'Order packing boxes', statusId: 'WeComplete', resolutionEnumId: 'WerCompleted', priority: 5,
        parentWorkEffortId: 'BOSS_DEMO_TASK_PLAN', rootWorkEffortId: 'BOSS_DEMO_PROJECT', estimatedCompletionDate: inDays(-1, '00:00'),
        actualCompletionDate: inDays(-1, '15:30')}, [[john, 'Assignee']])
    store('mantle.work.time.TimeEntry', {timeEntryId: 'BOSS_DEMO_TE_PLAN1', partyId: john, workEffortId: 'BOSS_DEMO_TASK_PLAN',
        rateTypeEnumId: 'RatpStandard', fromDate: inDays(-1, '09:00'), thruDate: inDays(-1, '11:00'), hours: 2,
        comments: 'Walked the new floor and listed the rooms'})

    // watched, from Joe, and the demo task again
    task('BOSS_DEMO_TASK_WATCH', {workEffortName: 'Renew the domain name', ownerPartyId: joe, priority: 3,
        description: 'The company domain expires at the end of the month.', estimatedCompletionDate: inDays(2, '12:00')},
        [[joe, 'Assignee'], [john, 'Watcher']])
    task('BOSS_DEMO_TASK_FROMJOE', {workEffortName: 'Check the backup restore', ownerPartyId: joe, priority: 4,
        description: 'Restore last night\'s backup to the spare machine and open a few files.'}, [[john, 'Assignee']])
    store('mantle.work.effort.WorkEffort', {workEffortId: 'BOSS_DEMO_TASK', estimatedCompletionDate: inDays(4, '17:00')})

    // the requests
    const request = (id, fields, parties) => {
        storeWithStatus('mantle.request.Request', 'requestId', Object.assign({requestId: id, requestTypeEnumId: 'RqtSupport', statusId: 'ReqSubmitted',
            requestResolutionEnumId: 'RrUnresolved', priority: 5, filedByPartyId: john, requestDate: inDays(-3, '10:00')}, fields))
        for (const [partyId, roleTypeId] of parties) store('mantle.request.RequestParty', {requestId: id, partyId: partyId, roleTypeId: roleTypeId,
            fromDate: fromDate})
        requestIdList.push(id)
    }
    request('BOSS_DEMO_REQ_DRAFT', {requestName: 'Order a second monitor', requestTypeEnumId: 'RqtPurchase', statusId: 'ReqDraft', priority: 5,
        description: 'A second 27 inch monitor for the design work.', requestDate: inDays(-1, '16:00')}, [[john, 'Reporter']])
    request('BOSS_DEMO_REQ_ASSIGNED', {requestName: 'Printer on the second floor jams', statusId: 'ReqInProgress', priority: 2, filedByPartyId: joe,
        description: 'It jams on every second page since Monday.', responseRequiredDate: inDays(3, '17:00')},
        [[joe, 'Reporter'], [john, 'Assignee']])
    request('BOSS_DEMO_REQ_WATCH', {requestName: 'Add a parking spot for visitors', requestTypeEnumId: 'RqtNewFeature', statusId: 'ReqReviewed',
        priority: 6, filedByPartyId: joe, description: 'Visitors park in the delivery bay.'}, [[joe, 'Reporter'], [john, 'Watcher']])
    request('BOSS_DEMO_REQ_DONE', {requestName: 'Reset the guest wifi password', statusId: 'ReqCompleted', requestResolutionEnumId: 'RrCompleted',
        priority: 4, requestDate: inDays(-10, '09:30')}, [[john, 'Reporter']])
} finally {
    if (!wasDisabled) ec.artifactExecution.enableAuthz()
    if (!signedIn && zone !== previousZone) ec.user.setTimeZone(previousZone || null)
}
